    public function useDocumentacionQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinDocumentacion($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Documentacion', 'DocumentacionQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   MediosMagneticos $mediosMagneticos Object to remove from the list of results
     *
     * @return MediosMagneticosQuery The current query, for fluid interface
     */
    public function prune($mediosMagneticos = null)
    {
        if ($mediosMagneticos) {
            $this->addUsingAlias(MediosMagneticosPeer::MEDIOSMAGNETICOS_ID, $mediosMagneticos->getMediosmagneticosId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
